    }
  `;

  // ---------- 工具函数 ----------
  function topWindow() {
    try { return window.top || window; } catch (_) { return window; }
  }
  function topDocument() {
    try { return topWindow().document || document; } catch (_) { return document; }
  }
  function context() {
    try {
      if (typeof SillyTavern !== 'undefined' && SillyTavern.getContext) return SillyTavern.getContext();
      const win = topWindow();
      if (win.SillyTavern && win.SillyTavern.getContext) return win.SillyTavern.getContext();
    } catch (_) {}
    return null;
  }

  function parseChoices(text) {
    if (!text) return [];
    const block = String(text).match(/<choice>([\s\S]*?)<\/choice>/i);
    if (!block) return [];
    const result = [];
    for (const rawLine of block[1].split(/\r?\n/)) {
      const line = rawLine.trim();
      if (!line) continue;
      const numbered = line.match(/^(?:\d+|[A-Za-zＡ-Ｚａ-ｚ]|[一二三四五六七八九十]+)[.、)）:：]\s*(.+)$/);
      const value = (numbered ? numbered[1] : line).trim();
      if (value) result.push(value);
    }
    return result;
  }

  function injectStyle(doc) {
    let style = doc.getElementById(STYLE_ID);
    if (!style) {
      style = doc.createElement('style');
      style.id = STYLE_ID;
      doc.head.appendChild(style);
    }
    if (style.textContent !== CSS) style.textContent = CSS;
  }

  function hideRenderedChoice(root) {
    if (!root) return;
    root.querySelectorAll('choice').forEach(node => { node.style.display = 'none'; });
    const doc = root.ownerDocument;
    const walker = doc.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    const nodes = [];
    let text = '';
    while (walker.nextNode()) {
      nodes.push({ node: walker.currentNode, start: text.length, end: text.length + walker.currentNode.nodeValue.length });
      text += walker.currentNode.nodeValue;
    }
    const match = /<choice>[\s\S]*?<\/choice>/i.exec(text);
    if (!match) return;
    const start = match.index;
    const end = start + match[0].length;
    const first = nodes.find(item => start >= item.start && start <= item.end);
    const last = nodes.find(item => end >= item.start && end <= item.end);
    if (!first || !last) return;
    const range = doc.createRange();
    range.setStart(first.node, Math.max(0, start - first.start));
    range.setEnd(last.node, Math.max(0, end - last.start));
    range.deleteContents();
  }

  // ---------- 发送核心 ----------
  function getDirectSend() {
    try {
      const val = localStorage.getItem(DIRECT_SEND_KEY);
      if (val !== null) return val === 'true';
    } catch (_) {}
    return true; // 默认开启
  }
  function setDirectSend(val) {
    try { localStorage.setItem(DIRECT_SEND_KEY, String(val)); } catch (_) {}
  }

  function writeAndSend(text, autoSend) {
    try {
      const doc = topDocument();
      const textarea = doc.getElementById('send_textarea');
      if (!textarea) return;
      if (autoSend) {
        textarea.value = text;
      } else {
        const cur = textarea.value;
        const sep = (cur && !cur.endsWith('\n')) ? ' ' : '';
        textarea.value = cur + sep + text;
      }
      textarea.dispatchEvent(new Event('input', { bubbles: true }));
      textarea.dispatchEvent(new Event('change', { bubbles: true }));
      if (autoSend) {
        const ctx = context();
        if (ctx && typeof ctx.generate === 'function') {
          ctx.generate();
        } else {
          const sendBtn = doc.getElementById('send_but');
          if (sendBtn) sendBtn.click();
        }
      }
    } catch (_) {}
  }

  // ---------- 构建卡片 ----------
  function buildCard(doc, messageIndex, options, collapsed, directSend) {
    const card = doc.createElement('section');
    card.className = 'tide-choice-card';
    card.dataset.owner = OWNER;
    card.dataset.messageIndex = String(messageIndex);
    card.dataset.signature = JSON.stringify(options);
    card.classList.toggle('collapsed', collapsed);

    // 头部
    const header = doc.createElement('div');
    header.className = 'tide-header';
    header.setAttribute('role', 'button');
    header.setAttribute('aria-expanded', String(!collapsed));
    header.setAttribute('aria-label', collapsed ? '展开行动选项' : '收起行动选项');

    // 图标
    const icon = doc.createElementNS('http://www.w3.org/2000/svg', 'svg');
    icon.setAttribute('class', 'tide-header-icon');
    icon.setAttribute('viewBox', '0 0 24 24');
    icon.setAttribute('fill', 'none');
    icon.setAttribute('stroke', 'currentColor');
    icon.setAttribute('stroke-width', '1.5');
    const path = doc.createElementNS('http://www.w3.org/2000/svg', 'path');
    path.setAttribute('stroke-linecap', 'round');
    path.setAttribute('stroke-linejoin', 'round');
    path.setAttribute('d', 'M12 2 L15.09 8.26 L22 9.27 L17 14.14 L18.18 21.02 L12 17.77 L5.82 21.02 L7 14.14 L2 9.27 L8.91 8.26 L12 2z');
    icon.appendChild(path);

    const title = doc.createElement('span');
    title.className = 'tide-header-title';
    title.textContent = '潮汐选择';

    // 控制区：直接发送开关 + 折叠指示器
    const controls = doc.createElement('span');
    controls.className = 'tide-header-controls';

    const toggleLabel = doc.createElement('span');
    toggleLabel.className = 'tide-toggle-label';
    toggleLabel.textContent = '发送';

    const toggle = doc.createElement('span');
    toggle.className = 'tide-toggle-switch' + (directSend ? ' active' : '');
    toggle.setAttribute('role', 'switch');
    toggle.setAttribute('aria-checked', String(directSend));
    toggle.addEventListener('click', (e) => {
      e.stopPropagation();
      const now = !toggle.classList.contains('active');
      toggle.classList.toggle('active', now);
      toggle.setAttribute('aria-checked', String(now));
      setDirectSend(now);
      // 更新所有同卡片内的开关状态保持一致（同一脚本内所有卡片共享同一设置）
      doc.querySelectorAll(`.tide-toggle-switch`).forEach(el => {
        el.classList.toggle('active', now);
        el.setAttribute('aria-checked', String(now));
      });
    });

    const collapseArrow = doc.createElement('span');
    collapseArrow.className = 'tide-collapse-indicator' + (collapsed ? ' collapsed' : '');
    collapseArrow.textContent = '▾';

    controls.append(toggleLabel, toggle, collapseArrow);
    header.append(icon, title, controls);

    // 折叠点击
    header.addEventListener('click', () => {
      const next = !card.classList.contains('collapsed');
      card.classList.toggle('collapsed', next);
      collapseArrow.classList.toggle('collapsed', next);
      header.setAttribute('aria-expanded', String(!next));
      try { localStorage.setItem(STORAGE_KEY, String(next)); } catch (_) {}
    });

    // 选项面板
    const panel = doc.createElement('div');
    panel.className = 'tide-options-panel';
    const list = doc.createElement('div');
    list.className = 'tide-option-list';

    if (options.length === 0) {
      const empty = doc.createElement('div');
      empty.className = 'tide-empty';
      empty.textContent = '🌊 没有可用的选择';
      list.appendChild(empty);
    } else {
      options.forEach((text, idx) => {
        const btn = doc.createElement('button');
        btn.className = 'tide-option-btn';
        const indexSpan = doc.createElement('span');
        indexSpan.className = 'tide-option-index';
        indexSpan.textContent = String(idx + 1).padStart(2, '0');
        const textSpan = doc.createElement('span');
        textSpan.className = 'tide-option-text';
        textSpan.textContent = text;
        btn.append(indexSpan, textSpan);
        btn.addEventListener('click', () => {
          // 获取当前开关状态（直接读取toggle的class，避免每次从storage读）
          const isDirect = toggle.classList.contains('active');
          writeAndSend(text, isDirect);
        });
        list.appendChild(btn);
      });
    }

    panel.appendChild(list);
    card.append(header, panel);
    return card;
  }

  function messageElement(doc, index) {
    return doc.querySelector(`.mes[mesid="${index}"]`) || doc.querySelector(`.mes[data-message-id="${index}"]`);
  }

  // ---------- 主循环 ----------
  const host = topWindow();
  if (host[GLOBAL_KEY] && typeof host[GLOBAL_KEY].destroy === 'function') host[GLOBAL_KEY].destroy();

  let stopped = false;
  let refreshTimer = 0;
  let pollTimer = 0;
  let observer = null;

  function refresh() {
    if (stopped) return;
    const doc = topDocument();
    injectStyle(doc);
    const ctx = context();
    const chat = (ctx && (ctx.chat || ctx.messages)) || [];
    const candidates = [];
    chat.forEach((message, index) => {
      if (!message) return;
      const assistant = message.role === 'assistant' || message.is_user === false || message.type === 'assistant';
      if (!assistant) return;
      const options = parseChoices(message.mes || message.message || message.content || '');
      if (options.length) candidates.push({ index, options });
    });
    const active = candidates.slice(-2); // 保留最近两条
    const wanted = new Set(active.map(item => String(item.index)));
    doc.querySelectorAll(`.tide-choice-card[data-owner="${OWNER}"]`).forEach(card => {
      if (!wanted.has(card.dataset.messageIndex)) card.remove();
    });

    let collapsed = false;
    try { collapsed = localStorage.getItem(STORAGE_KEY) === 'true'; } catch (_) {}
    const directSend = getDirectSend();

    active.forEach(item => {
      const message = messageElement(doc, item.index);
      if (!message) return;
      const content = message.querySelector('.mes_text') || message.querySelector('.message_text') || message;
      hideRenderedChoice(content);
      const signature = JSON.stringify(item.options);
      const existing = message.querySelector(`.tide-choice-card[data-owner="${OWNER}"][data-message-index="${item.index}"]`);
      if (existing && existing.dataset.signature === signature) return;
      if (existing) existing.remove();
      content.insertAdjacentElement('afterend', buildCard(doc, item.index, item.options, collapsed, directSend));
    });
  }

  function scheduleRefresh() {
    clearTimeout(refreshTimer);
    refreshTimer = setTimeout(refresh, 80);
  }

  const doc = topDocument();
  injectStyle(doc);
  observer = new MutationObserver(scheduleRefresh);
  observer.observe(doc.getElementById('chat') || doc.body, { childList: true, subtree: true });
  pollTimer = setInterval(refresh, 900);
  refresh();

  function destroy() {
    stopped = true;
    clearTimeout(refreshTimer);
    clearInterval(pollTimer);
    if (observer) observer.disconnect();
    const currentDoc = topDocument();
    currentDoc.getElementById(STYLE_ID)?.remove();
    currentDoc.querySelectorAll(`.tide-choice-card[data-owner="${OWNER}"]`).forEach(card => card.remove());
  }

  host[GLOBAL_KEY] = { destroy, refresh };
})();

